document.querySelectorAll(".edube-btn-border").forEach((function(button){button.addEventListener("click",(function(){const target=this.getAttribute("data-bs-target"),others=document.querySelectorAll(".collapse.show");others.forEach((function(element){element.id!==target.slice(1)&&element.classList.remove("show")}));const targetElement=document.querySelector(target);targetElement.classList.add("show"),document.querySelectorAll(".edube-btn-border").forEach((function(btn){btn.classList.remove("show")})),this.classList.add("show")}))}));